export async function pollOnce(id: string): Promise<Status> {
  const max = 5;
  for (let i = 0; i < max; i++) {
    const s = await probe(id);
    if (s.ready) return s;
    await sleep(250 * (i + 1));
  }
  throw new Error("not ready");
}

